  {rt::GlobalFetchOverride fetch(mock([](auto,auto,auto){return h::voyageOkResponse(1,511);}));AWAIT(response,h::handleEmbeddingsJobCreate(jobRequest("wrong-job-length",json::object{{"dimensions",512}}),token));EXPECT_EQ(response.status(),200);EXPECT_EQ(response.headers().get("x-uos-upstream"),"voyage");AWAIT(body,response.json());EXPECT_EQ(rt::getString(body,"status"),"failed");const auto error=rt::get(body,"error");EXPECT_EQ(rt::getString(*error,"code"),"embeddings_job_upstream_dimension_mismatch");EXPECT(std::string(rt::getString(*error,"message").value()).find("length 511; expected 512")!=std::string::npos);id=std::string(rt::getString(body,"id").value());}
  rt::GlobalFetchOverride fetch(noFetch());AWAIT(polled,poll(id,token));EXPECT_EQ(polled.status(),200);EXPECT_EQ(polled.headers().get("x-uos-upstream"),"voyage");AWAIT(body,polled.json());EXPECT_EQ(rt::getString(body,"status"),"failed");EXPECT_EQ(rt::getString(*rt::get(body,"error"),"code"),"embeddings_job_upstream_dimension_mismatch");
